"use client";

import React, { useState, useMemo } from "react";
import PageHeader from "@/components/common/PageHeader";
import { Upload, Calendar as CalendarIcon, Info, CheckCircle2 } from "lucide-react";

// Types for better safety
type LeaveType = "annual" | "sick" | "casual" | "comp_off" | "maternity" | "unpaid";

export default function RequestAbsencePage() {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formData, setFormData] = useState({
        leaveType: "annual" as LeaveType,
        startDate: "",
        endDate: "",
        duration: "full",
        reason: "",
        files: null as FileList | null,
    });

    // Elite Touch: Dynamic Calculation of requested days
    const requestedDays = useMemo(() => {
        if (!formData.startDate || !formData.endDate) return 0;
        const start = new Date(formData.startDate);
        const end = new Date(formData.endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
        return formData.duration === "full" ? diffDays : 0.5;
    }, [formData.startDate, formData.endDate, formData.duration]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        
        // Simulate API Call
        await new Promise(resolve => setTimeout(resolve, 1500));
        
        setIsSubmitting(false);
        alert("Absence request submitted for approval.");
    };

    return (
        <div className="mx-auto max-w-6xl px-4 py-8">
            <PageHeader
                title="Request Absence"
                subtitle="Submit a leave request. Your manager will be notified automatically."
                breadcrumbs={[{ label: "Time Management" }, { label: "Request Absence" }]}
            />

            <div className="mt-8 grid grid-cols-1 gap-8 lg:grid-cols-3">
                {/* Left Column: The Form */}
                <div className="lg:col-span-2">
                    <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                                {/* Leave Type */}
                                <div className="space-y-2">
                                    <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Leave Type</label>
                                    <select
                                        name="leaveType"
                                        value={formData.leaveType}
                                        onChange={handleChange}
                                        className="w-full rounded-lg border border-gray-300 bg-transparent px-4 py-3 text-sm outline-none transition focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 dark:border-gray-700"
                                    >
                                        <option value="annual">Annual Leave (Paid)</option>
                                        <option value="sick">Sick Leave</option>
                                        <option value="casual">Casual Leave</option>
                                        <option value="comp_off">Comp Off</option>
                                    </select>
                                </div>

                                {/* Requested Duration Info */}
                                <div className="flex items-center rounded-lg bg-blue-50 p-4 dark:bg-blue-500/5">
                                    <Info className="mr-3 h-5 w-5 text-blue-600" />
                                    <div>
                                        <p className="text-xs text-blue-700 dark:text-blue-400 uppercase font-bold">Estimated Duration</p>
                                        <p className="text-lg font-semibold text-blue-900 dark:text-blue-100">{requestedDays} Working Days</p>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Start Date</label>
                                    <input type="date" name="startDate" onChange={handleChange} className="w-full rounded-lg border p-3 text-sm dark:bg-transparent dark:border-gray-700" required />
                                </div>

                                <div className="space-y-2">
                                    <label className="text-sm font-medium">End Date</label>
                                    <input type="date" name="endDate" min={formData.startDate} onChange={handleChange} className="w-full rounded-lg border p-3 text-sm dark:bg-transparent dark:border-gray-700" required />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium">Reason for Absence</label>
                                <textarea
                                    name="reason"
                                    rows={3}
                                    placeholder="Provide details for your manager..."
                                    className="w-full rounded-lg border border-gray-300 bg-transparent px-4 py-3 text-sm outline-none focus:border-blue-500 dark:border-gray-700"
                                    required
                                />
                            </div>

                            {/* Conditional Upload: Only for Sick Leave */}
                            {formData.leaveType === "sick" && (
                                <div className="rounded-xl border-2 border-dashed border-gray-200 p-8 text-center dark:border-gray-800">
                                    <Upload className="mx-auto h-8 w-8 text-gray-400" />
                                    <p className="mt-2 text-sm text-gray-500">Medical certificate required for sick leave &gt; 2 days</p>
                                    <input type="file" className="mt-4 text-xs" />
                                </div>
                            )}

                            <div className="flex items-center justify-end gap-3 border-t pt-6 dark:border-gray-800">
                                <button type="button" className="text-sm font-medium text-gray-600 hover:text-gray-800">Save as Draft</button>
                                <button
                                    type="submit"
                                    disabled={isSubmitting}
                                    className="rounded-lg bg-blue-600 px-8 py-3 text-sm font-bold text-white transition hover:bg-blue-700 disabled:opacity-50"
                                >
                                    {isSubmitting ? "Processing..." : "Submit Request"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>

                {/* Right Column: Balance Summary */}
                <div className="space-y-6">
                    <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
                        <h3 className="text-lg font-bold">Leave Balance</h3>
                        <div className="mt-4 space-y-4">
                            <BalanceRow label="Annual Leave" used={12} total={25} color="bg-blue-500" />
                            <BalanceRow label="Sick Leave" used={2} total={10} color="bg-emerald-500" />
                            <BalanceRow label="Casual Leave" used={4} total={7} color="bg-amber-500" />
                        </div>
                    </div>
                    
                    <div className="rounded-xl bg-gray-50 p-4 dark:bg-white/5">
                        <div className="flex gap-3">
                            <CheckCircle2 className="h-5 w-5 text-emerald-500" />
                            <p className="text-xs text-gray-600 dark:text-gray-400">
                                Your request will be sent to <strong>Sarah Jenkins</strong> (Direct Manager) for approval.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

// Helper Component for the Sidebar
function BalanceRow({ label, used, total, color }: { label: string; used: number; total: number; color: string }) {
    const percentage = (used / total) * 100;
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-sm">
                <span className="text-gray-500">{label}</span>
                <span className="font-medium">{total - used} left</span>
            </div>
            <div className="h-2 w-full rounded-full bg-gray-100 dark:bg-gray-800">
                <div className={`h-2 rounded-full ${color}`} style={{ width: `${percentage}%` }} />
            </div>
        </div>
    );
}